CREATE TABLE "arena_owners" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"display_name" text NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "arena_devices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"display_name" text NOT NULL,"device_type" text NOT NULL,"enrollment_provenance" text NOT NULL,"node_public_key" text,"last_activity_at" timestamp,"revoked_at" timestamp,"revocation_reason" text,"state" text DEFAULT 'active' NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "webauthn_credentials" ("id" text PRIMARY KEY,"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"device_id" uuid NOT NULL REFERENCES "arena_devices"("id") ON DELETE CASCADE,"public_key" text NOT NULL,"counter" integer DEFAULT 0 NOT NULL,"transports" text DEFAULT '[]' NOT NULL,"device_type" text,"backed_up" boolean DEFAULT false NOT NULL,"revoked_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL,"last_used_at" timestamp);
CREATE TABLE "auth_challenges" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid REFERENCES "arena_owners"("id") ON DELETE CASCADE,"device_id" uuid REFERENCES "arena_devices"("id") ON DELETE CASCADE,"kind" text NOT NULL,"challenge" text NOT NULL,"expires_at" timestamp NOT NULL,"consumed_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "authenticated_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"token_hash" text UNIQUE NOT NULL,"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"device_id" uuid NOT NULL REFERENCES "arena_devices"("id") ON DELETE CASCADE,"credential_id" text NOT NULL REFERENCES "webauthn_credentials"("id"),"authentication_method" text DEFAULT 'webauthn' NOT NULL,"assurance" text DEFAULT 'user_verified' NOT NULL,"fresh_verified_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL,"expires_at" timestamp NOT NULL,"last_activity_at" timestamp DEFAULT now() NOT NULL,"revoked_at" timestamp);
CREATE TABLE "device_capability_grants" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"device_id" uuid NOT NULL REFERENCES "arena_devices"("id") ON DELETE CASCADE,"capability" text NOT NULL,"resource" text NOT NULL,"scope" text NOT NULL,"effect_class" text,"created_at" timestamp DEFAULT now() NOT NULL,"expires_at" timestamp,"revoked_at" timestamp,"created_by_device_id" uuid REFERENCES "arena_devices"("id"));
CREATE TABLE "security_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid REFERENCES "arena_owners"("id") ON DELETE SET NULL,"device_id" uuid REFERENCES "arena_devices"("id") ON DELETE SET NULL,"authenticated_session_id" uuid REFERENCES "authenticated_sessions"("id") ON DELETE SET NULL,"type" text NOT NULL,"outcome" text NOT NULL,"metadata" text DEFAULT '{}' NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX "auth_sessions_token_idx" ON "authenticated_sessions"("token_hash"); CREATE INDEX "device_grants_lookup_idx" ON "device_capability_grants"("device_id","capability","resource"); CREATE INDEX "security_events_owner_idx" ON "security_events"("owner_id","created_at");
